checks.solution:
def run(facts, rules):
    facts = set(facts)
    fired = set()
    count = 0
    while True:
        agenda = []
        for order, (name, salience, match, action) in enumerate(rules):
            for key in match(facts):
                if (name, key) not in fired:
                    agenda.append((-salience, order, name, key, action))
        if not agenda:
            return facts, count
        agenda.sort(key=lambda item: item[:2])
        _, _, name, key, action = agenda[0]
        fired.add((name, key))
        facts |= set(action(key))
        count += 1

checks.test:
def haired(facts):
    return [f for f in facts if f[0] == "animal" and f[2] == "has-hair"]

def warm(key):
    return [("animal", key[1], "warm-blooded")]

wm, n = run({("animal", "dog", "has-hair")}, [("mammal", 0, haired, warm)])
assert n == 1, n
assert ("animal", "dog", "warm-blooded") in wm, sorted(wm)

def flu_match(facts):
    return [("flu",)] if {("symptom", "fever"), ("symptom", "aches")} <= facts else []

def flu_fire(key):
    return [("diagnosis", "flu")]

def cold_match(facts):
    if ("symptom", "runny-nose") in facts and ("diagnosis", "flu") not in facts:
        return [("cold",)]
    return []

def cold_fire(key):
    return [("diagnosis", "cold")]

symptoms = {("symptom", "fever"), ("symptom", "aches"), ("symptom", "runny-nose")}
cold_rule = ("cold", 0, cold_match, cold_fire)

wm, n = run(symptoms, [cold_rule, ("flu", 10, flu_match, flu_fire)])
assert ("diagnosis", "flu") in wm and ("diagnosis", "cold") not in wm, sorted(wm)
assert n == 1, n

wm, n = run(symptoms, [cold_rule, ("flu", 0, flu_match, flu_fire)])
assert n == 2 and {("diagnosis", "cold"), ("diagnosis", "flu")} <= wm, (n, sorted(wm))

def tick_match(facts):
    return [f for f in facts if f[0] == "tick"]

def tick_fire(key):
    return [("tick", key[1])]

wm, n = run({("tick", 1)}, [("echo", 0, tick_match, tick_fire)])
assert n == 1, "the same activation must not fire a second time"

assert run(set(), []) == (set(), 0)
